package dev.gamersclt.batcaverna.nativeapp;
import org.json.*;
import java.text.Normalizer;
import java.util.*;
/** Catalog hints are conservative: an absent year never proves two editions are identical. */
final class CatalogSelection {
 static String key(String text){return Normalizer.normalize(text==null?"":text,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase(Locale.ROOT).replaceAll("[™®]","").replaceAll("[^\\p{L}\\p{N}]+"," ").trim();}
 static String name(JSONObject item){return item.optString("nome",item.optString("name",""));}
 static String year(JSONObject item){String raw=item.optString("ano",item.optString("released",""));return raw.matches("[12][0-9]{3}.*")?raw.substring(0,4):"";}
 static String typeLabel(boolean media,int type){return !media?"Jogo":type==2?"Anime":type==1?"Série":"Filme";}
 static String kind(boolean media,int type){return !media?"jogos":type==2?"animes":type==1?"series":"filmes";}
 static final class Match {final String state;final JSONObject row;Match(String state,JSONObject row){this.state=state;this.row=row;}}
 static Match match(JSONObject source,boolean media,int type,JSONArray library){String title=key(name(source)),year=year(source);if(title.isEmpty())return new Match("new",null);JSONObject possible=null,variant=null;for(int i=0;i<library.length();i++){JSONObject row=library.optJSONObject(i);if(row==null||"jogos".equals(row.optString("categoria"))==media)continue;if(!media&&source.optLong("steam_appid")>0&&source.optLong("steam_appid")==row.optLong("steam_appid"))return new Match("owned",row);String oldYear=year(row),base=name(row),oldKind=HomeResumePolicy.kind(row);String oldType=oldKind.equals("jogos")?"Jogo":oldKind.equals("series")?"Série":oldKind.equals("animes")?"Anime":"Filme";for(String suffix:new String[]{" ("+oldYear+")"," ("+oldYear+" · "+oldType+")"})if(!oldYear.isEmpty()&&base.endsWith(suffix)){base=base.substring(0,base.length()-suffix.length());break;}if(!key(base).equals(title))continue;if(!oldKind.equals(kind(media,type))||!media&&source.optLong("steam_appid")>0&&row.optLong("steam_appid")>0&&source.optLong("steam_appid")!=row.optLong("steam_appid")||!year.isEmpty()&&!oldYear.isEmpty()&&!year.equals(oldYear)){variant=row;continue;}if(!year.isEmpty()&&year.equals(oldYear))return new Match("owned",row);possible=row;}return possible!=null?new Match("possible",possible):variant!=null?new Match("variant",variant):new Match("new",null);}
 static String label(String state){return state.equals("owned")?"✓ Já na biblioteca · abrir título":state.equals("possible")?"Possível cadastro · confira antes de adicionar":state.equals("variant")?"Outra versão ou tipo na biblioteca":"Selecionar para adicionar";}
 static String meta(JSONObject item,boolean media,int type){List<String> parts=new ArrayList<>();String year=year(item);parts.add(year.isEmpty()?"Ano não informado":year);parts.add(typeLabel(media,type));if(!media){String name=name(item).toLowerCase(Locale.ROOT);if(name.contains("remaster"))parts.add("Remaster");else if(name.contains("remake"))parts.add("Remake");else if(name.matches(".*(edition|edição|deluxe|ultimate|definitive|goty).*"))parts.add("Edição especial");JSONArray platforms=item.optJSONArray("platforms");List<String> names=new ArrayList<>();for(int i=0;platforms!=null&&i<Math.min(3,platforms.length());i++){JSONObject p=platforms.optJSONObject(i);if(p==null)continue;JSONObject nested=p.optJSONObject("platform");String value=(nested==null?p:nested).optString("name");if(!value.isEmpty())names.add(value);}parts.add(names.isEmpty()?"Plataformas não informadas":android.text.TextUtils.join(", ",names)+(platforms.length()>3?" +"+(platforms.length()-3):""));}return android.text.TextUtils.join(" · ",parts);}
 static String qualified(JSONObject source,boolean media,int type,Match match){String title=name(source),year=year(source);if(!match.state.equals("variant")||year.isEmpty()||!key(name(match.row)).equals(key(title)))return title;return title+" ("+year+(year.equals(year(match.row))?" · "+typeLabel(media,type):"")+")";}
}
